\begin{ex}%[8H3H3]
\immini[thm]{
Cho hình bình hành ${GHFE}$. Trên cạnh ${GH}$ lấy điểm ${I}$ trên cạnh ${FE}$ lấy điểm ${J}$ sao cho $GI=FJ$. Chọn khẳng sai trong các khẳng định sau?

\choice
{ ${GIFJ}$ là hình bình hành  }
   { \True $\Delta { HFJ } =\Delta {IEG}$  }
     {  ${HI=EJ}$ }
    {  ${EIHJ}$ là hình bình hành }
}{
\begin{tikzpicture}
            \coordinate (M) at (-2.34, 1.31);
            \coordinate (D) at (2, 0);
            \coordinate (C) at (3, 2);
            \coordinate (B) at (-2, 2);
            \coordinate (A) at (-3, 0);
            \coordinate (N) at (2.34, 0.69);
            % Vẽ tứ giác
            \draw[thick] (D) -- (M) ;
            \draw[thick] (A) -- (B)--(C)--(D)--(A);
        \draw[thick] (N) -- (B) ;
            % Ghi nhãn các điểm
            \node[above left] at (M) {$I$};
            \node[above left] at (B) {$H$};
            \node[above right] at (C) {$F$};
            \node[below right] at (D) {$E$};
            \node[below left] at (A){$G$};
            \node[below right] at (N) {$J$};
            \draw
        ($(A)!0.5!(M)$)node[rotate=20]{$/$} ($(N)!0.5!(C)$)node[rotate=20]{$/$};
    \end{tikzpicture}
}
\loigiai{
${GHFE}$ là hình hành nên $GH//FE$ suy ra $GI//FJ$\\
Và $GI=FJ$ nên ${GIFJ }$ là hình bình hành\\
$GH=FE, GI=FJ$ nên $HI=EJ$ suy ra ${EIHJ}$ là hình bình hành vì có 2 cạnh đối song song và bằng nhau\\
Tương tự ta có ${GIFJ}$ là hình bình hành\\
Khẳng định sai là $\Delta { HFJ } =\Delta {IEG}$  sửa đúng là $\Delta { HFJ } =\Delta {EIG}$
}\end{ex}

