Cho hình bình hành ${MNPQ}$. Trên cạnh ${MN}$ lấy điểm ${E}$ trên cạnh ${PQ}$ lấy điểm ${F}$ sao cho $ME=PF$. Chọn khẳng sai trong các khẳng định sau?

\choice
{  ${QENF}$ là hình bình hành }
   { \True $\Delta { NPF } =\Delta {EQM}$  }
     { ${MEPF}$ là hình bình hành  }
    {  ${NE=QF}$ }
}{
\begin{tikzpicture}
            \coordinate (M) at (-2.34, 1.31);
            \coordinate (D) at (2, 0);
            \coordinate (C) at (3, 2);
            \coordinate (B) at (-2, 2);
            \coordinate (A) at (-3, 0);
            \coordinate (N) at (2.34, 0.69);
            % Vẽ tứ giác
            \draw[thick] (D) -- (M) ;
            \draw[thick] (A) -- (B)--(C)--(D)--(A);
        \draw[thick] (N) -- (B) ;
            % Ghi nhãn các điểm
            \node[above left] at (M) {$E$};
            \node[above left] at (B) {$N$};
            \node[above right] at (C) {$P$};
            \node[below right] at (D) {$Q$};
            \node[below left] at (A){$M$};
            \node[below right] at (N) {$F$};
            \draw
        ($(A)!0.5!(M)$)node[rotate=20]{$/$} ($(N)!0.5!(C)$)node[rotate=20]{$/$};
    \end{tikzpicture}
}
\loigiai{
${MNPQ}$ là hình hành nên $MN//PQ$ suy ra $ME//PF$\\
Và $ME=PF$ nên ${MEPF }$ là hình bình hành\\
$MN=PQ, ME=PF$ nên $NE=QF$ suy ra ${QENF}$ là hình bình hành vì có 2 cạnh đối song song và bằng nhau\\
Tương tự ta có ${MEPF}$ là hình bình hành\\
Khẳng định sai là $\Delta { NPF } =\Delta {EQM}$  sửa đúng là $\Delta { NPF } =\Delta {QEM}$
}\end{ex}

\begin{ex}%[8H3H3]
